package com.finanscore.report.infrastructure;import io.minio.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.io.*;@Component public class MinioReportStorage{private final MinioClient client;private final String bucket;public MinioReportStorage(@Value("${app.minio.endpoint:http://minio:9000}")String endpoint,@Value("${app.minio.access-key:minioadmin}")String access,@Value("${app.minio.secret-key}")String secret,@Value("${app.minio.bucket:scoring-reports}")String bucket){this.client=MinioClient.builder().endpoint(endpoint).credentials(access,secret).build();this.bucket=bucket;}public void put(String key,byte[] bytes)throws Exception{boolean exists=client.bucketExists(BucketExistsArgs.builder().bucket(bucket).build());if(!exists)client.makeBucket(MakeBucketArgs.builder().bucket(bucket).build());client.putObject(PutObjectArgs.builder().bucket(bucket).object(key).stream(new ByteArrayInputStream(bytes),bytes.length,-1).contentType("application/pdf").build());}public InputStream get(String key)throws Exception{return client.getObject(GetObjectArgs.builder().bucket(bucket).object(key).build());}}